<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pcap.js?13"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Platform/manage')}" class="on">平台分类列表</a>|					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/add')}','添加分类',800,560,true,false,false,addbtn,'add',true);">添加分类</a>					<a href="{pigcms{:U('Platform/activity_list')}">平台活动列表</a>|					<a href="{pigcms{:U('Platform/checkList')}">分类管理员审核列表</a>|					<a href="{pigcms{:U('Platform/examine_refundList')}">退款审核列表</a>|					<a href="{pigcms{:U('Platform/platform_config')}">配置项</a>|				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td style="width:60%;">						<form action="{pigcms{:U('Platform/manage')}" method="get">							<input type="hidden" name="c" value="Platform"/>							<input type="hidden" name="a" value="manage"/>							筛选: 							<if condition="$admin_area neq 3">							<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}"  style="display:inline"></div>							</if>							<input type="submit" value="查询" class="button"/>						</form>					</td>					<!-- <td><font style="color:red">只有设置了二级分类</font>且<font style="color:red;">必须拥有该分类的活动</font>,才会在wap端申请管理员页面查看到</td> -->				</tr>			</table>							<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col> <col><col><col><col><col><col width="240" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>								<th>排序</th>								<th>所属区域</th>								<th>分类名称</th>								<th>下属分类</th>								<th>状态</th>								<th>添加时间</th>								<th>开启/关闭</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.sort}</td>										<td>{pigcms{$vo.province_name}{pigcms{$vo.city_name}</td>										<td>{pigcms{$vo.cate_name}</td>										<td><a href="{pigcms{:U('Platform/classify',array('id'=>$vo['id']))}">查看子分类</a></td>										<td>											<if condition="$vo['status'] eq 0">													开启											<else/>													关闭											</if>											</td>										<td><if condition="$vo['add_time']">{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}<else/>无</if></td>										<td>											<span class="cb-enable"><label class="cb-enable <if condition="$vo['status'] eq 0">selected</if>"><span onclick="discoverSwitch('{pigcms{$vo.id}', 0)" >开启</span><input type="radio" value="0" <if condition="$vo['status'] eq 0">checked="checked"</if> /></label></span>                                            <span class="cb-disable"><label class="cb-disable <if condition="$vo['status'] eq 1">selected</if>"><span onclick="discoverSwitch('{pigcms{$vo.id}', 1)">关闭</span><input type="radio" value="1" <if condition="$vo['status'] eq 1">checked="checked"</if> /></label></span>										</td>										<td>										<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/edit',array('id'=>$vo['id']))}','编辑信息',800,560,true,false,false,editbtn,'edit',true);">编辑</a> |																				<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Platform/del_cate')}">删除</a>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>				</div><script>   var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('Merchant/export_info')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><script>            var lockInfo = false;            function discoverSwitch(id, status) {            	console.log(id);                if (lockInfo) return;                lockInfo = true;                var url = '';                var close_category = "{pigcms{:U('Platform/close_cate')}";                var open_category = "{pigcms{:U('Platform/open_cate')}";                if (0 == status) {                    url = open_category;                } else if(1 == status) {                    url = close_category;                } else {                    return;                }                $.post(url,{'id': id},function(data){                    console.log(data)                    if (data && (data.status === 1 || data.status === '1')) {                        location.reload();                    } else {                        alert(data.info)                    }                },'json')                setTimeout(function(){                    lockInfo = false;                },1000);            }        </script><include file="Public:footer"/>